func mitbProtectionPlannedOptionalString(configured, planned types.String, name string, maximum int, diagnostics *diag.Diagnostics) *string {
	if configured.IsNull() {
		// Omission preserves the prior state value carried into the plan by
		// use_state_for_unknown; a null planned value (e.g. a clear-string
		// modifier) drops the field so the backend removes it.
		if !planned.IsNull() && !planned.IsUnknown() {
			value := planned.ValueString()
			if maximum > 0 && utf8.RuneCountInString(value) > maximum {
				diagnostics.AddError("Invalid MITB protection item", fmt.Sprintf("The %s exceeds %d UTF-8 characters.", name, maximum))
			}
			return &value
		}
		return nil
	}
	value := ""
	if configured.IsUnknown() {
		if planned.IsNull() {
			return nil
		}
		if planned.IsUnknown() {
			diagnostics.AddError("Unknown MITB protection item", "The configured "+name+" is still unknown during apply.")
			return nil
		}
		value = planned.ValueString()
	} else {
		value = configured.ValueString()
	}
	if maximum > 0 && utf8.RuneCountInString(value) > maximum {
		diagnostics.AddError("Invalid MITB protection item", fmt.Sprintf("The %s exceeds %d UTF-8 characters.", name, maximum))
	}
	return &value
}
