func mitbProtectionDecodeOptionalInt64(object map[string]json.RawMessage, key, location string, diagnostics *diag.Diagnostics) int64 {
	raw, ok := object[key]
	if !ok || mitbProtectionJSONNull(raw) {
		return 0
	}
	var number json.Number
	if err := json.Unmarshal(raw, &number); err != nil {
		diagnostics.AddError("Malformed MITB protection result", location+" "+key+" was not an integer.")
		return 0
	}
	value, err := number.Int64()
	if err != nil {
		diagnostics.AddError("Malformed MITB protection result", location+" "+key+" was not an integer.")
		return 0
	}
	return value
}

// DecodeOptionalInt64WithDefault decodes an optional integer item field,
// substituting the reviewed default when the successful GET omits the key or
// returns null. This mirrors the encode path (PlannedOptionalInt64 sends the
// reviewed default when the practitioner omits the field), so state carries the
// reviewed default rather than 0 and a later update does not reuse a stale 0.
